def validate_target_size(target_size):
    import re
    pattern = r'^\d+x\d+$'
    if not re.match(pattern, target_size):
        raise ValueError("Invalid targetSize format. Expected format: 'WIDTHxHEIGHT'.")

# Example usage
try:
    validate_target_size("500x500")
    print("Valid target size")
except ValueError as e:
    print(e)
